fn merge(a: { ...r }, b: { ...s }): { ...r, ...s }
  where r disjoint s = { ...a, ...b };
fn merge3(a: { ...r }, b: { ...s }, c: { ...t }): { ...r, ...s, ...t }
  = merge(merge(a, b), c);
fn apply3(f: (a, b, c) -> { x: Int, y: Int, z: Int }, w: c, p: a,
    q: b): Int = 0;
fn main(): Int = apply3(merge3, { v: 3 }, { x: 1 }, { y: 2 });
